+#!/usr/bin/env node
+
+function parseArguments(args) {
+  let bill;
+  let percent;
+
+  for (let index = 0; index < args.length; index += 1) {
+    const argument = args[index];
+    if (argument === '--percent') {
+      if (percent !== undefined) {
+        throw new Error('Enter --percent once, with a percentage from 0 to 100.');
+      }
+      percent = args[++index];
+    } else if (argument.startsWith('--')) {
+      throw new Error(`Unknown option ${argument}. Use a bill amount and --percent from 0 to 100.`);
+    } else if (bill === undefined) {
+      bill = argument;
+    } else {
+      throw new Error('Enter one bill amount, followed by --percent from 0 to 100.');
+    }
+  }
+
+  if (bill === undefined || !/^[0-9]+(?:\.[0-9]{1,2})?$/.test(bill)) {
+    throw new Error('Enter a bill amount of 0 or more with at most two decimal places.');
+  }
+  if (percent === undefined || !/^[0-9]+(?:\.[0-9]+)?$/.test(percent)) {
+    throw new Error('Enter --percent with a percentage from 0 to 100.');
+  }
+
+  const [billWhole, billFraction = ''] = bill.split('.');
+  const billCents = BigInt(billWhole) * 100n + BigInt(billFraction.padEnd(2, '0') || '0');
+  const [percentWhole, percentFraction = ''] = percent.split('.');
+  const scale = 10n ** BigInt(percentFraction.length);
+  const percentUnits = BigInt(percentWhole) * scale + BigInt(percentFraction || '0');
+  if (percentUnits > 100n * scale) {
+    throw new Error('Enter --percent with a percentage from 0 to 100.');
+  }
+
+  return { billCents, percentUnits, scale };
+}
+
+function formatMoney(cents) {
+  return `$${cents / 100n}.${String(cents % 100n).padStart(2, '0')}`;
+}
+
+try {
+  const { billCents, percentUnits, scale } = parseArguments(process.argv.slice(2));
+  const divisor = 100n * scale;
+  const tipCents = (billCents * percentUnits * 2n + divisor) / (2n * divisor);
+  const totalCents = billCents + tipCents;
+  console.log(`Tip: ${formatMoney(tipCents)}  Total: ${formatMoney(totalCents)}`);
+} catch (error) {
+  console.error(`Error: ${error.message}`);
+  process.exitCode = 1;
+}
